targets.expr:
max by (bucket, bucket_namespace, name, source, version, endpoint) (
  label_join(webtech_s3_exporter_info{bucket_namespace=~"$namespace", name=~"$bucket"}, "bucket", "/", "bucket_namespace", "name")
)

max by (bucket) (
  label_join(sum by (bucket_namespace, name) (increase(webtech_s3_bucket_probe_errors_total{bucket_namespace=~"$namespace", name=~"$bucket"}[1h])), "bucket", "/", "bucket_namespace", "name")
)

max by (bucket, reason) (
  label_join(topk by (bucket_namespace, name) (1, increase(webtech_s3_bucket_probe_errors_total{bucket_namespace=~"$namespace", name=~"$bucket"}[1h]) > 0), "bucket", "/", "bucket_namespace", "name")
)
